{# the cap applies to the refresh, not to its callback (days * 2) #}
{% if meta.run.kind == "refresh" and args.days > 30 %}{% set args.days = 30 %}{% endif %}
SELECT {{ args.days }} AS days, {{ args.days }} * 100 + abs(random() % 50) AS orders

query.transform:
if meta.run.kind == "callback" then return rs end   -- the callback's rows, as they are
local wider = dbdash.run({ days = args.days * 2 }).rows[1]
return { columns = { "days", "orders", "days_2x", "orders_2x" },
         rows = { { rs.rows[1][1], rs.rows[1][2], wider[1], wider[2] } } }

query.sql:
{% import 'modules/callbacks.lua' as cb %}
SELECT {{ args.days }} AS days, {{ args.days }} * 100 + abs(random() % 50) AS orders,
       {{ cb.orders(args.days * 2) if meta.run.kind == "refresh" else 'NULL' }} AS orders_2x

query.transform:
-- Keep each refresh's result in a list (the last 20) and show the list.
store.history = store.history or {}
table.insert(store.history, { at = os.date("%H:%M:%S"), orders = rs.rows[1][1] })
while #store.history > 20 do
  table.remove(store.history, 1)
end
return { columns = { "at", "orders" }, rows = vim.tbl_map(function(h)
  return { h.at, h.orders }
end, store.history) }
